  if(chosen.State=="Outstanding"){
   if(chosen.Kind==ContractKindD.Exchange){ui.Button(new(right,row,180,27),"ACCEPT EXCHANGE",()=>NoticeD(world.AcceptExchangeD(chosen.Id)),"Stage D accept exchange");ui.Button(new(right+190,row,210,27),"INVITE NPC PURCHASE",()=>NpcAcceptExchangeD(chosen),"Stage D NPC purchase");}
   if(chosen.Kind==ContractKindD.Courier){ui.Button(new(right,row,180,27),"ACCEPT AS CARRIER",()=>NoticeD(world.AcceptCourierD(chosen.Id,"player")),"Stage D accept courier");ui.Button(new(right+190,row,210,27),"HIRE FUNDED NPC HAULER",()=>{var pilots=world.Population.Pilots.Where(p=>p.Home==chosen.Origin&&p.Role is "Hauler" or "Trader").ToArray();ShowPopup("Carrier / available funds",pilots.Select(p=>(p.Name+" / "+p.Wallet+" CR",(Action)(()=>NoticeD(world.AcceptCourierD(chosen.Id,p.Id))))));},"Stage D hire courier");}
   if(chosen.Kind==ContractKindD.Auction){ui.Button(new(right,row,180,27),"BID PRICE FIELD",()=>NoticeD(world.BidAuctionD(chosen.Id,"player",NumberD("price"))),"Stage D bid auction");ui.Button(new(right+190,row,210,27),"INVITE FUNDED NPC BID",()=>NpcBidD(chosen),"Stage D NPC bid");}
   row+=36;ui.Button(new(right,row,180,27),"CANCEL OUTSTANDING",()=>NoticeD(world.CancelContractD(chosen.Id)),"Stage D cancel contract");
  }
  if(chosen.State=="In progress"){ui.Button(new(right,row,180,27),"DELIVER SEALED PACKAGE",()=>NoticeD(world.CompleteCourierD(chosen.Id)),"Stage D deliver courier");if(chosen.Issuer=="player")ui.Button(new(right+190,row,210,27),"FAIL AFTER DEADLINE",()=>NoticeD(world.FailCourierD(chosen.Id,true)),"Stage D deadline failure");row+=36;ui.Button(new(right,row,180,27),"BREAK OWN PACKAGE",()=>NoticeD(world.BreakCourierPackageD(chosen.Id)),"Stage D break package");}
  if(chosen.State=="Finished"){ui.Button(new(right,row,180,27),"CLAIM MY AUCTION",()=>NoticeD(world.ClaimAuctionD(chosen.Id,"player")),"Stage D claim auction");ui.Button(new(right+190,row,210,27),"NPC CLAIMS PURCHASE",()=>NoticeD(world.ClaimAuctionD(chosen.Id,chosen.Bidder)),"Stage D NPC auction claim");}
 }
 void NpcAcceptExchangeD(ContractD c){var b=world.Population.Businesses.FirstOrDefault(b=>b.Station==c.Origin&&b.Wallet>=c.Price&&c.Items.Sum(i=>ItemCatalog.Get(i.Key).Price*i.Value)>=c.Price);NoticeD(b==null?"No local business values the lot above its price.":world.AcceptExchangeD(c.Id,b.Id));}
 void NpcBidD(ContractD c){decimal bid=c.Bidder.Length==0?c.Price:c.BidEscrow+Math.Max(.01m,Math.Round(c.BidEscrow*.1m,2));decimal value=c.Items.Sum(i=>ItemCatalog.Get(i.Key).Price*i.Value);var b=world.Population.Businesses.FirstOrDefault(b=>b.Station==c.Origin&&b.Id!=c.Bidder&&b.Wallet>=bid&&value>=bid);NoticeD(b==null?"No funded local business values the next bid.":world.BidAuctionD(c.Id,b.Id,bid));}
