  ui.Text("FINITE RESEARCH / SPECIAL ACQUISITION",right,y,Cyan,14);ui.Text("Science III | standing 0.1 | research service",right,y+30,Muted,12);ui.Text("24 hours + 5 salvage + 100 CR > 5 datacores",right,y+59,Gold,12);ui.Button(new(right,y+101,425,29),"START DATACORE RESEARCH",()=>NoticeD(world.StartResearchD()),"Stage D start research");
  int row=y+150;foreach(var job in world.Commander.Research.TakeLast(6)){var r=job;ui.Text(ShortInfo(world.AssetLocationD(r.Station)+" / "+(r.Claimed?"CLAIMED":r.Finish<=world.Now?"READY":r.Finish.ToString("u")),55),right,row,White,12);ui.Button(new(right+330,row-5,95,26),"CLAIM",()=>NoticeD(world.ClaimResearchD(r.Id)),"Stage D claim research / "+r.Id);row+=36;}
  ui.Button(new(right,row+19,425,29),"2-RUN ANALYZER BPC / 5 DATACORES + 100 CR",()=>NoticeD(world.RedeemDatacoresD()),"Stage D research blueprint");ui.Text("SP items, implants, books, tags, datacores and vouchers",right,row+68,Muted,12);ui.Text("cannot be manufactured from generic mineral recipes.",right,row+94,Muted,12);
 }
 void SetupCommanderCaptureD(){world.NewGame(0);world.WalletFunds=100000;world.Hangar["ammo"]=100;world.Hangar["ore"]=120;desktop.Clear();OpenCommanderD();commanderTabD=captureScene switch{"stage-d-assets"=>2,"stage-d-trade"=>3,"stage-d-contracts"=>4,"stage-d-rewards"=>5,"stage-d-recovery"=>1,_=>0};world.CreateFitPlanD();
  if(captureScene=="stage-d-contracts"){string next=world.Current.Links.First();world.EnsurePopulationC(next);contractDestinationD=next;contractKindD=2;var c=world.CreateContractD(ContractKindD.Courier,"Regional supplies",new(){["ammo"]=20},next,reward:30,collateral:100)!;commanderSelectedD=c.Id;world.AcceptCourierD(c.Id,world.Population.Pilots.First(p=>p.Home==world.StationKey44&&p.Role=="Hauler").Id);}
  if(captureScene=="stage-d-recovery"){world.InsureShipD("Platinum");world.RecoveryStationId=world.StationKey44;world.Screen=ViewMode.Space;world.Grid="belt";world.CargoItems["rail"]=4;world.LosePlayerD();world.LosePlayerD();commanderSelectedD=world.Commander.Losses.First().Id;}
 }
 int commanderUiChecksD;
 void RunCommanderUiChecksD(int frame)
 {
  void Check(bool ok,string name){if(!ok)throw new Exception("STAGE D UI FAIL: "+name);commanderUiChecksD++;Console.WriteLine("STAGE D UI PASS: "+name);}void Click(string tip)=>TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());
  switch(frame){case 0:Check(desktop.Any(w=>w.Kind==ViewMode.Commander),"Commander window opens");Click("Stage D buy / d_injector");Check(world.Hangar["d_injector"]==1,"Purchase creates physical injector");break;case 1:Click("Stage D consume injector");Check(world.Hangar["d_injector"]==0&&world.Skills.Unallocated>0,"Consume button settles SP item once");Click("Stage D tab / Assets");break;case 2:Click("Stage D create container");Check(world.Commander.Containers.Count==1,"Container creation button");break;case 3:Click("Stage D container transfer");Check(world.Commander.Containers[0].Items["ammo"]==20,"Local transfer uses selected storage");Click("Stage D tab / Trade");break;case 4:Click("Stage D add multibuy");Check(multiBuyDraftD.Count==1,"Multibuy draft button");break;case 5:Click("Stage D execute multibuy");Check(multiBuyDraftD.Count==0&&world.MarketTrades.Count>0,"Multibuy button executes real trades");Click("Stage D tab / Contracts");break;case 6:Click("Stage D create contract");Check(world.Commander.Contracts.Count==1,"Exchange contract button reserves items");break;case 7:Click("Stage D cancel contract");Check(world.Commander.Contracts[0].State=="Cancelled","Cancel button returns reserved items");Click("Stage D tab / Rewards");break;case 8:Check(ui.Hits.Any(h=>h.Tip=="Stage D LP blueprint")&&ui.Hits.Any(h=>h.Tip=="Stage D start research"),"Reward acquisition controls available");Click("Stage D tab / Recovery");break;case 9:Check(ui.Hits.Any(h=>h.Tip=="Stage D insure"),"Insurance and medical-home controls available");Click("Stage D tab / Character");break;case 10:Click("Stage D create fit plan");Check(world.Commander.Masteries.Count==2,"Fit plan button creates permanent milestones");Check(world.PopulationMoneyErrorC==0,"Commercial UI preserves population ledger");Console.WriteLine(commanderUiChecksD+" Stage D UI checks passed.");break;
  }
 }
